-- =====================================================================================================
-- Glacier · Datenbank · 04_startdaten.sql
-- ERZEUGT aus com.dan.glacier.data.Startdaten (tools.StartdatenSql) – nicht von Hand ändern.
-- Mitgelieferte Zeilen (HERKUNFT = 'MITGELIEFERT') werden angelegt oder wiederhergestellt; eigene Zeilen
-- bleiben unberührt. Beliebig oft wiederholbar. Gelände und Fronten sind aus der Szene gerechnet (Gelände
-- aus daten/gelaende, Prüfsummen in GLC_GELAENDE); die Rupturas aus data/ruptura.txt (recherchiert am
-- 18.10.2026, Quellen in GLC_QUELLE).
-- =====================================================================================================
-- ZAHLEN: Quellen=23; Befunde=27; Belege=25; Gelände=1; Fronten=13; Rupturas=32; Wetterlagen=12; Regiebücher=3; Stichworte=77; Ansichten=8; Fahrten=3; Presets=64; Presetwerte=960;

-- Die Quellen enthalten „&“: in SQL Developer keine Ersetzungsvariablen
SET DEFINE OFF

-- ----------------------------------------------------------------------------------------- Ausbaustufe
MERGE INTO GLC_SCHEMA t USING (SELECT 1 AS VERSION FROM DUAL) q ON (t.VERSION = q.VERSION)
WHEN NOT MATCHED THEN INSERT (VERSION, APP_VERSION, TEXT) VALUES (1, 'Phase 15', 'Oberfläche und Datenbank: 21 Tabellen, die Chronik von Front, Kalbung, Eisbergen und Ruptura, Regiebücher als Text, Befunde');

