MERGE INTO GLC_REGIEBUCH t USING (SELECT 'Ein Sommertag an der Front' AS NAME FROM DUAL) q ON (t.NAME = q.NAME)
WHEN MATCHED THEN UPDATE SET t.BESCHREIBUNG = '16.1.2026, 6 bis 22 Uhr im Zeitraffer 60: Seenebel am Morgen, Kalbungen über den Tag, der Katamaran, auf dem Eis, durch die Spalte, abends Licht von Westen', t.DATEI = 'sommertag.txt', t.SZENENZEIT = TIMESTAMP '2026-01-16 06:00:00', t.ZEITRAFFER = 60, t.LAENGE_S = 961, t.FOTOS = 10, t.BLATT = 1, t.WETTER = 'Wetter: 06:00 | 60' || CHR(10) || 'Schritt: 2.5 | NEBEL | Seenebel vor der Front | WIND=1 DIRECTION=270 COVER=1 FOG=0.8 VISIBILITY=4 TEMPERATURE=6 HUMIDITY=95 | Vom Steg' || CHR(10) || 'Schritt: 1.5 | KLAR | Der Nebel hebt sich | WIND=3 DIRECTION=270 FOG=0.2 COVER=1 VISIBILITY=30 TEMPERATURE=10 HUMIDITY=80 | Südflanke' || CHR(10) || 'Schritt: 7 | KLAR | Ein klarer Sommertag, Westwind vom Eisfeld | WIND=6 DIRECTION=275 COVER=2 VISIBILITY=60 FOG=0 TEMPERATURE=16 HUMIDITY=55 | Vom Boot' || CHR(10) || 'Schritt: 5 | KLAR | Abend, Licht von Westen | WIND=4 DIRECTION=280 COVER=3 VISIBILITY=60 TEMPERATURE=12 HUMIDITY=60 | Vom Steg' || CHR(10) || '' WHERE t.HERKUNFT = 'MITGELIEFERT'
WHEN NOT MATCHED THEN INSERT (NAME, LAENGE_S, TEXT, HERKUNFT) VALUES ('Ein Sommertag an der Front', 961, '-', 'MITGELIEFERT');
UPDATE GLC_REGIEBUCH t SET t.BESCHREIBUNG = '16.1.2026, 6 bis 22 Uhr im Zeitraffer 60: Seenebel am Morgen, Kalbungen über den Tag, der Katamaran, auf dem Eis, durch die Spalte, abends Licht von Westen', t.DATEI = 'sommertag.txt', t.SZENENZEIT = TIMESTAMP '2026-01-16 06:00:00', t.ZEITRAFFER = 60, t.LAENGE_S = 961, t.FOTOS = 10, t.BLATT = 1, t.WETTER = 'Wetter: 06:00 | 60' || CHR(10) || 'Schritt: 2.5 | NEBEL | Seenebel vor der Front | WIND=1 DIRECTION=270 COVER=1 FOG=0.8 VISIBILITY=4 TEMPERATURE=6 HUMIDITY=95 | Vom Steg' || CHR(10) || 'Schritt: 1.5 | KLAR | Der Nebel hebt sich | WIND=3 DIRECTION=270 FOG=0.2 COVER=1 VISIBILITY=30 TEMPERATURE=10 HUMIDITY=80 | Südflanke' || CHR(10) || 'Schritt: 7 | KLAR | Ein klarer Sommertag, Westwind vom Eisfeld | WIND=6 DIRECTION=275 COVER=2 VISIBILITY=60 FOG=0 TEMPERATURE=16 HUMIDITY=55 | Vom Boot' || CHR(10) || 'Schritt: 5 | KLAR | Abend, Licht von Westen | WIND=4 DIRECTION=280 COVER=3 VISIBILITY=60 TEMPERATURE=12 HUMIDITY=60 | Vom Steg' || CHR(10) || '',
  t.TEXT = TO_CLOB('# Glacier · Regiebuch (Phase 14). Eine Zeile je Stichwort: Zeit (Minuten:Sekunden echte Zeit), Befehl, Argumente, nach' || CHR(10) || '# „ | “ der Text fürs HUD. Mehrere Befehle zur selben Zeit sind ein Stichwort. Befehle: zeit, raffer, wetter,' || CHR(10) || '# wetter_frei, ansicht, fahrt, boot, aussteigen, kalbung, kalbung_regie, ruptura, damm, figuren, foto, blatt, sage.' || CHR(10) || '# Gestaltet [G].' || CHR(10) || 'Regiebuch: Ein Sommertag an der Front' || CHR(10) || 'Beschreibung: 16.1.2026, 6 bis 22 Uhr im Zeitraffer 60: Seenebel am Morgen, Kalbungen über den Tag, der Katamaran, auf dem Eis, durch die Spalte, abends Licht von Westen' || CHR(10) || 'Länge: 16:01' || CHR(10) || 'Wetter: 06:00 | 60' || CHR(10) || 'Schritt: 2.5 | NEBEL | Seenebel vor der Front | WIND=1 DIRECTION=270 COVER=1 FOG=0.8 VISIBILITY=4 TEMPERATURE=6 HUMIDITY=95 | Vom Steg' || CHR(10) || 'Schritt: 1.5 | KLAR | Der Nebel hebt sich | WIND=3 DIRECTION=270 FOG=0.2 COVER=1 VISIBILITY=30 TEMPERATURE=10 HUMIDITY=80 | Südflanke' || CHR(10) || 'Schritt: 7 | KLAR | Ein klarer Sommertag, Westwind vom Eisfeld | WIND=6 DIRECTION=275 COVER=2 VISIBILITY=60 FOG=0 TEMPERATURE=16 ')
